		return "pub" // Dart
	case strings.HasSuffix(m.Filename, "Package.resolved"):
		return "swift" // Swift
	case strings.HasSuffix(m.Filename, ".yml"),
		strings.HasSuffix(m.Filename, ".yaml"):
		return "actions" // GitHub Actions workflows
	default:
		return "unknown"
	}
}

